select t.work_id::text||':'||t.language as key,md5(jsonb_build_object('bound_author_id',t."bound_author_id",'evidence',t."evidence",'language',t."language",'provenance',t."provenance",'review_batch',t."review_batch",'review_status',t."review_status",'reviewed_at',t."reviewed_at",'source_name',t."source_name",'source_type',t."source_type",'source_url',t."source_url",'text',t."text",'work_id',t."work_id")::text) as digest from public.catalog_work_descriptions t order by t.work_id,t.language;
